import React from "react"
import { Card, CardContent, Typography, cn } from "@heroui/react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import type { ReactNode } from "react"

/** Track accent — maps to a semantic theme token. */
export type TrackColor = "accent" | "success" | "warning"

/** One tier (rung) on a track's foundation→application path. */
export interface TrackTier {
    /** Tier name (eyebrow), e.g. "Foundation". */
    label: string
    /** What you learn at this tier, e.g. "HTTP, REST, data modeling". */
    topic: string
}

/** Props for {@link TrackCard}. */
export interface TrackCardProps {
    /** Leading icon (bare phosphor icon — tile sizes it). */
    icon: ReactNode
    /** Track title, e.g. "Real-World Fullstack". */
    title: string
    /** Meta line, e.g. "23 modules · 20 systems". */
    meta: string
    /** Accent token driving dot / line / icon-tile / CTA colour. */
    color: TrackColor
    /** The 4 tiers, foundation → application (rendered as a vertical path). */
    tiers: ReadonlyArray<TrackTier>
    /** CTA label, e.g. "Go to course". */
    viewLabel: string
    /** CTA handler → navigate to the course. */
    onView: () => void
    /** Class on the outer card (sizing / placement). */
}

const DOT: Record<TrackColor, string> = { accent: "bg-accent", success: "bg-success", warning: "bg-warning" }
const LINE: Record<TrackColor, string> = { accent: "bg-accent/25", success: "bg-success/25", warning: "bg-warning/25" }
const TILE: Record<TrackColor, string> = {
    accent: "bg-accent-soft text-accent-soft-foreground",
    success: "bg-success-soft text-success-soft-foreground",
    warning: "bg-warning-soft text-warning-soft-foreground",
}
const CTA: Record<TrackColor, string> = { accent: "text-accent-soft-foreground", success: "text-success-soft-foreground", warning: "text-warning-soft-foreground" }

/**
 * A learning-track card for the landing "Roadmap" section: identity header
 * (icon tile + title + meta) over a vertical 4-tier path (foundation →
 * application, each rung = coloured dot + tier eyebrow + topic) with a "Go to course"
 * CTA pinned to the bottom. Self-contained bounded object — render 3 side-by-side
 * (`@app-md:grid-cols-3 gap-6`) so the tracks read + compare without a shared-axis
 * matrix. Colour comes from one semantic token via {@link TrackColor}.
 *
 * @param props - {@link TrackCardProps}
 */
export const TrackCard = ({ icon, title, meta, color, tiers, viewLabel, onView }: TrackCardProps) => (
    <Card className="h-full">
        <CardContent className="flex h-full flex-col gap-6">
            <div className="flex items-center gap-3">
                <span className={cn("flex size-10 shrink-0 items-center justify-center rounded-xl [&>svg]:size-5", TILE[color])}>
                    {icon}
                </span>
                <div className="flex min-w-0 flex-col">
                    <Typography type="body" weight="semibold" className="truncate">
                        {title}
                    </Typography>
                    <Typography type="body-xs" color="muted">
                        {meta}
                    </Typography>
                </div>
            </div>

            <div className="flex flex-col">
                {tiers.map((tier, index) => (
                    <div key={tier.label} className="flex gap-3">
                        <div className="flex flex-col items-center">
                            <span className={cn("mt-1 size-2.5 shrink-0 rounded-full", DOT[color])} />
                            {index < tiers.length - 1 ? <span className={cn("my-1 w-px flex-1", LINE[color])} /> : null}
                        </div>
                        <div className={cn("flex flex-col gap-0", index < tiers.length - 1 && "pb-4")}>
                            <Typography type="body-xs" color="muted">
                                {tier.label}
                            </Typography>
                            <Typography type="body-sm">
                                {tier.topic}
                            </Typography>
                        </div>
                    </div>
                ))}
            </div>

            <button
                type="button"
                onClick={onView}
                className={cn("group mt-auto inline-flex cursor-pointer items-center gap-1 self-start text-sm font-medium", CTA[color])}
            >
                {viewLabel}
                <ArrowRightIcon aria-hidden focusable="false" className="size-4 transition-transform group-hover:translate-x-0.5" />
            </button>
        </CardContent>
    </Card>
)

import React from "react"
import { Accordion, Typography } from "@heroui/react"
/** One blunt truth + how the product answers it. */
export interface TruthListItem {
    /** The uncomfortable truth (the headline statement). */
    truth: React.ReactNode
    /** What we do about it (the proof line — keep it concrete). */
    fix: React.ReactNode
}

/** Props for the {@link TruthList} block. */
export interface TruthListProps {
    /** Ordered truths — each a broken industry reality + the product's answer. */
    items: Array<TruthListItem>
    /** Optional signature footer (who is saying this) — e.g. a founder byline. */
    byline?: React.ReactNode
}

/**
 * A "raw truth" manifesto: a list of uncomfortable industry truths, each paired
 * with a concrete "→ here's our answer" line, closed
 * by an optional byline (who's saying it). Built for confrontational, grounded
 * positioning — the truths are the hero, the author recedes to a signature.
 * Tier-3 block on {@link SectionCard}; styling here, content via props.
 *
 * @param props - {@link TruthListProps}
 */
export const TruthList = ({ items, byline}: TruthListProps) => {
    return (
        <div className={"overflow-hidden rounded-3xl bg-surface shadow-surface"}>
            {/* Accordion Card: p-0 flush frame, the accordion surface owns its background + separators + corner radius.
                Each truth = a trigger (statement) that opens its explanation. NO Accordion.Indicator
                → no caret (teacher's ruling); the trigger hover is the affordance. */}
            <Accordion variant="surface" className="!rounded-none [&_*]:!rounded-none">
                {/* the accordion is fully square → the outer frame (overflow-hidden rounded-3xl) owns the radius;
                    the last item sits flush with the byline and never bleeds a rounded edge on hover. */}
                {items.map((item, index) => (
                    <Accordion.Item
                        key={index}
                        aria-label={typeof item.truth === "string" ? item.truth : `truth-${index}`}
                    >
                        <Accordion.Heading>
                            <Accordion.Trigger>
                                <Typography type="body" weight="medium" className="text-left">
                                    {item.truth}
                                </Typography>
                            </Accordion.Trigger>
                        </Accordion.Heading>
                        <Accordion.Panel>
                            <Accordion.Body>
                                <Typography type="body-sm" color="muted">
                                    {item.fix}
                                </Typography>
                            </Accordion.Body>
                        </Accordion.Panel>
                    </Accordion.Item>
                ))}
            </Accordion>
            {byline ? (
                <div className="flex flex-wrap items-center gap-3 border-t border-default px-5 py-4">
                    {byline}
                </div>
            ) : null}
        </div>
    )
}

