"use client"

import React, { createContext, useContext, useEffect, useState } from "react"
import type { ReactNode } from "react"
import { motion, AnimatePresence, useReducedMotion } from "framer-motion"
import { cn } from "@heroui/react"
import { SidebarSimpleIcon } from "@phosphor-icons/react"
import { ButtonBase } from "@/components/atoms/buttons/Button/ButtonBase"
import { Typography } from "@/components/atoms/text/Typography"
import { DragScrollArea } from "@/components/behaviors/DragScrollArea"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { NavigationRail } from "@/components/frames/NavigationRail"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `CollapsibleSidebar` — a content-agnostic shell for a left navigation sidebar
 * that collapses in place (no overlay/Drawer). Owns collapse/expand, the width
 * animation, persisting the choice to `localStorage`, and a `useSidebarCollapsed`
 * context so nav-row content can self-adapt to the icon-only rail. It never
 * inspects `children`. One leaf: `topSlot` presence and the collapsed flag are
 * data, so they are states, not separate leaves.
 */

/** Expanded panel width (full nav). */
const EXPANDED_WIDTH = "16rem"
/** Collapsed rail width — fits a centered icon row + the toggle. */
const COLLAPSED_WIDTH = "4rem"

/**
 * Named transition shapes (not inline object literals at the call site — check-inline-types
 * gate) for the width animation: a spring when motion is welcome, instant when the reader (or
 * their OS) asked for reduced motion.
 */
const SPRING_TRANSITION = { type: "spring" as const, stiffness: 420, damping: 38 }
const INSTANT_TRANSITION = { duration: 0 }
/** Title fade — quick cross-fade, same instant fallback under reduced motion. */
const FADE_TRANSITION = { duration: 0.15 }

/**
 * Collapsed flag shared with nav-row children so a row can drop to icon-only in
 * the rail. Internal UI chrome state — not an app store.
 */
const SidebarCollapsedContext = createContext(false)

/** Read whether the surrounding {@link CollapsibleSidebar} is collapsed (icon-rail). */
export const useSidebarCollapsed = (): boolean => useContext(SidebarCollapsedContext)

/** Props for the {@link CollapsibleSidebar} composite. */
export interface CollapsibleSidebarProps {
    /** Heading shown in the panel header (hidden while collapsed). */
    title: string
    /** Accessible label for the collapse toggle (expanded state). */
    collapseLabel: string
    /** Accessible label for the expand toggle (collapsed state). */
    expandLabel: string
    /**
     * Stable key under which the collapsed flag persists in `localStorage`, so
     * the choice survives navigation between pages that share this sidebar.
     */
    storageKey: string
    /**
     * Optional node pinned BETWEEN the header and the scrollable nav — always
     * visible (outside the scroll area). Rendered inside the collapsed-context
     * provider, so it can adapt to the rail (e.g. a resume pill → play icon).
     */
    topSlot?: ReactNode
    /** The panel body — nav rows/groups; content-agnostic, this shell never inspects them. */
    children: ReactNode
    /**
     * Placement utilities only. Retained while forbidden mia-mia consumers still
     * pass a height/layout class; StarCi callers should prefer parent frames.
     */
    className?: string
}

/**
 * A left navigation sidebar that collapses IN PLACE: the panel animates between
 * a full {@link EXPANDED_WIDTH} (title + nav) and a thin {@link COLLAPSED_WIDTH}
 * rail (just the toggle), and the surrounding content reflows beside it — no
 * overlay/Drawer. Self-contained: the collapsed state is local UI chrome,
 * hydrated from storage on mount (SSR-safe — starts expanded, then syncs).
 *
 * @param props - {@link CollapsibleSidebarProps}
 */
export const CollapsibleSidebar = ({
    title,
    collapseLabel,
    expandLabel,
    storageKey,
    topSlot,
    children,
    className,
}: CollapsibleSidebarProps) => {
    const reduceMotion = useReducedMotion()
    const [collapsed, setCollapsed] = useState(false)

    // hydrate the persisted choice after mount (avoids SSR/client mismatch)
    useEffect(() => {
        const stored = window.localStorage.getItem(storageKey)
        if (stored !== null) {
            setCollapsed(stored === "true")
        }
    }, [storageKey])

    /** Flip + persist the collapsed flag. */
    const toggle = () => {
        setCollapsed((prev) => {
            const next = !prev
            window.localStorage.setItem(storageKey, String(next))
            return next
        })
    }

    // §10a: the vertical rhythm between header / topSlot / nav is owned by THIS
    // StackV's gap — no section carries its own margin (a prior draft put
    // `mb-6` on the header row itself, flagged by check-padding as a second
    // owner for the same seam).
    return (
        <SidebarCollapsedContext.Provider value={collapsed}>
            <motion.aside

                initial={false}
                animate={{ width: collapsed ? COLLAPSED_WIDTH : EXPANDED_WIDTH }}
                transition={reduceMotion ? INSTANT_TRANSITION : SPRING_TRANSITION}
                className={cn(
                    // ONE padding wrapper for the whole rail: p-6 expanded / px-3 py-6
                    // collapsed. No frame in this tree types an asymmetric inset, so this
                    // stays hand-written on the composite's own bespoke root (§13c precedent:
                    // Toolbar/ModalShell/DrawerShell do the same on theirs).
                    "flex h-full shrink-0 overflow-hidden border-r border-default",
                    collapsed ? "px-3 py-6" : "p-6",
                    className,
                )}
            >
                <StackV
                    identity={{ tier: "block", component: "CollapsibleSidebar" }}
                    gap={6}
                    classNames={["min-h-0", "flex-1"]}
                    principle="group-boundary"
                    explain="Separates header, pinned top slot, and scrollable nav so each region keeps its own seam owner — not sibling-stack, because these are distinct section roles rather than repeating peers."
                    items={[
                        () => (
                            <StackH
                                gap={3}
                                principle="flex-action"
                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                justify={collapsed ? "center" : "between"}
                                items={[
                                    () => (
                                        <AnimatePresence initial={false}>
                                            {!collapsed ? (
                                                <motion.div
                                                    key="title"
                                                    initial={{ opacity: 0 }}
                                                    animate={{ opacity: 1 }}
                                                    exit={{ opacity: 0 }}
                                                    transition={reduceMotion ? INSTANT_TRANSITION : FADE_TRANSITION}
                                                    className="min-w-0"
                                                >
                                                    <Typography
                                                        size="h5"
                                                        weight="bold"
                                                        truncate
                                                        text={title}
                                                    />
                                                </motion.div>
                                            ) : null}
                                        </AnimatePresence>
                                    ),
                                    () => (
                                        <ButtonBase
                                            isIconOnly
                                            variant="ghost"
                                            size="sm"
                                            ariaLabel={collapsed ? expandLabel : collapseLabel}
                                            prefixIcon={SidebarSimpleIcon}
                                            onPress={toggle}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        // pinned top slot (e.g. resume pill) — above the scroll area, always
                        // visible. min-w-0: a column-flex item defaults to content-width
                        // (min-width: auto), which would let it overflow the rail and get
                        // hard-clipped by overflow-hidden instead of shrinking so its own
                        // `truncate` text can ellipsize.
                        () => (
                            <FillAvailable
                                at="base"
                                body={() => <>{topSlot}</>}
                            />
                        ),
                        // body: the nav — ALWAYS rendered; row content decides its own icon-only
                        // look off `useSidebarCollapsed`. `NavigationRail` owns the `<nav>`
                        // landmark + column flex-fill; `DragScrollArea` owns the overflow
                        // (hidden scrollbar + Windows-safe pointer-pan); inner `StackV` gives
                        // the column its `gap={4}` rhythm and default `align="stretch"` (rows
                        // fill the rail's width whether expanded or collapsed).
                        () => (
                            <NavigationRail
                                body={() => (
                                    <DragScrollArea size={40} className="flex-1">
                                        <StackV
                                            gap={4}
                                            principle="sibling-stack"
                                            explain="Same-kind peer stack of nav rows — not group-boundary, because rows are repeating siblings rather than section groups."
                                            items={[() => children]}
                                        />
                                    </DragScrollArea>
                                )}
                            />
                        ),
                    ]}
                />
            </motion.aside>
        </SidebarCollapsedContext.Provider>
    )
}

"use client"

import React from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    CheckCircleIcon,
    CircleIcon,
    LockIcon,
    StarIcon,
} from "@phosphor-icons/react"
import type {
    ReactNode,
} from "react"
/** Props for the {@link ContentMapRow} block. */
export interface ContentMapRowProps {
    /** Lesson title (the row's accessible name). */
    title: string
    /** Highlights the row as the lesson currently open. */
    isActive: boolean
    /** Read (green check) — highest-priority status marker. */
    isRead: boolean
    /** Locked (lock) — the viewer cannot open it yet (no access). */
    isLocked?: boolean
    /** Premium / VIP (star) — unlocked once enrolled; shown when not locked. */
    isPremium: boolean
    /** Optional right-aligned meta (e.g. the minutes-read label). */
    meta?: ReactNode
    /** Fired when the row is pressed (navigation handled by the caller). */
    onPress: () => void
}

/**
 * Single status marker per row, by priority: read → green check; locked → lock;
 * premium (accessible) → star; otherwise the plain "unread / reading" circle. Thin
 * outline icons (no fill weight); only the read state carries a (success) colour —
 * the rest stay neutral/muted.
 */
const resolveStatus = ({ isRead, isLocked, isPremium }: Pick<ContentMapRowProps, "isRead" | "isLocked" | "isPremium">) => {
    if (isRead) {
        return { Icon: CheckCircleIcon, tone: "text-success-soft-foreground" }
    }
    if (isLocked) {
        return { Icon: LockIcon, tone: "text-foreground" }
    }
    if (isPremium) {
        return { Icon: StarIcon, tone: "text-foreground" }
    }
    return { Icon: CircleIcon, tone: "text-foreground" }
}

/**
 * A single compact lesson row for the course content-map rail: a read marker, the
 * title (two-line clamp), an optional premium lock, and right-aligned meta. The
 * whole row is one press target; the active lesson gets an accent tint. Pure +
 * props-only — owns its look so features only compose it.
 *
 * @param props - {@link ContentMapRowProps}
 */
export const ContentMapRow = ({
    title,
    isActive,
    isRead,
    isLocked = false,
    isPremium,
    meta,
    onPress}: ContentMapRowProps) => {
    const { Icon, tone } = resolveStatus({ isRead, isLocked, isPremium })
    return (
        <button
            type="button"
            onClick={onPress}
            className={cn("flex w-full items-start gap-2 rounded-xl px-2 py-2 text-left transition-colors",
                isActive ? "bg-accent-soft" : "hover:bg-surface-secondary")}
        >
            {/* one thin status marker per row (read / locked / premium / unread) */}
            <Icon aria-hidden focusable="false" className={cn("mt-0 size-5 shrink-0", tone)} />
            <Typography
                type="body-sm"
                className={cn("line-clamp-2 min-w-0 flex-1", isActive && "text-accent-soft-foreground")}
            >
                {title}
            </Typography>
            {meta ? <span className="mt-0 shrink-0">{meta}</span> : null}
        </button>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { Tabs, cn } from "@heroui/react"

/** Props for the {@link ExtendedTabs} block. */
export interface ExtendedTabsProps {
    /** Currently selected tab id (controlled). */
    selectedKey: string
    /** Fired with the newly selected tab id. */
    onSelectionChange: (key: string) => void
    /**
     * Tab anatomy — keep using the HeroUI compound parts inside:
     * `Tabs.ListContainer` > `Tabs.List` > `Tabs.Tab` (+ `Tabs.Indicator`).
     */
    children: ReactNode
    /**
     * HeroUI `Tabs` variant. `"secondary"` (default) = in-page CONTENT tabs —
     * hugs its own label width (packs left, `.extended-tabs` override), no
     * outer baseline (the feature wrapper owns any full-width chrome; see
     * `TabsCard` §1). `"primary"` = page-FEATURE tabs that switch the ENTIRE
     * panel content — HeroUI's own default rendering (segmented pill,
     * full-width, evenly-stretched tabs), untouched by the `.extended-tabs`
     * hug-content override. Use `"primary"` for top-level section switches
     * (e.g. Begin/History/Stats), `"secondary"` for a content filter/
     * language-switcher riding alongside a reading column.
     */
    variant?: "primary" | "secondary"
    /**
     * `"md"` (default) = full-width (`w-full`), evenly-stretched tabs — the
     * only size this block used to support. `"sm"` shrinks a `"primary"` tab
     * strip to `w-fit` (segments size to their label, don't stretch) — for a
     * compact secondary choice that shouldn't claim the full row (e.g. a
     * setting nested inside a modal panel). Has no effect on `"secondary"`
     * (already hug-content via `.extended-tabs`).
     */
    size?: "sm" | "md"
}

/**
 * The StarCi standard tab strip: a thin wrapper over the HeroUI `Tabs` root.
 * `variant="secondary"` (default) bakes in the underline look — foreground text
 * on the selected tab + an accent indicator — and drops the built-in
 * `.tabs__list` baseline (so it never doubles up with an outer separator; see
 * `.extended-tabs` in globals.css). `variant="primary"` renders HeroUI's plain
 * default Tabs (full-width segmented pill) for page-level feature switches.
 * Drop-in replacement for `<Tabs>`; the children still use the `Tabs.*`
 * compound parts. Use this instead of styling `Tabs` per-feature.
 *
 * @param props - {@link ExtendedTabsProps}
 * @see Story: .storybook/stories/blocks/navigation/ExtendedTabs/ExtendedTabs.stories
 */
export const ExtendedTabs = ({
    selectedKey,
    onSelectionChange,
    children,
    variant = "secondary",
    size = "md"}: ExtendedTabsProps) => {
    return (
        <Tabs
            variant={variant}
            selectedKey={selectedKey}
            onSelectionChange={(key) => onSelectionChange(String(key))}
            className={cn(// tab labels must never wrap to a 2nd line — white-space inherits down to
                // every Tabs.Tab, so a squeezed segment truncates (w-full) or sizes to the
                // one-line label (w-fit) instead of stacking words.
                "whitespace-nowrap",
                variant === "secondary" ? "extended-tabs" : size === "sm" ? "w-fit" : "w-full")}
        >
            {children}
        </Tabs>
    )
}

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Button, ButtonGroup, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One selectable button in a {@link FlexWrapButtonRadio}. */
export interface FlexWrapButtonRadioItem<T extends string> {
    /** Value selected when this button is chosen. */
    value: T
    /** Button content (icon + label + meta — caller-defined inline row). */
    content: ReactNode
    /** When true the button is dimmed and not selectable. */
    isDisabled?: boolean
}

/** Props shared by both the single- and multi-select modes of {@link FlexWrapButtonRadio}. */
interface FlexWrapButtonRadioBaseProps<T extends string> extends WithClassNames<undefined> {
    /** The selectable buttons. */
    items: Array<FlexWrapButtonRadioItem<T>>
    /** Accessible label for the group. */
    ariaLabel: string
    /**
     * Optional trailing node placed after the buttons in the SAME row (e.g. a
     * "+N" overflow button). Not part of the group's value — it's an action.
     */
    trailing?: ReactNode
    /**
     * Optional per-item trailing action(s) — e.g. a delete button and/or a "..."
     * (kebab) menu trigger. When provided, the item's select button and these
     * action buttons render as ONE connected {@link ButtonGroup} per item
     * (`[select | delete | ...]`) — touching, a full-height separator at every seam,
     * rounded only at the two outer ends — instead of a detached button floating
     * beside the pill. Return the action `<Button>`s as an ARRAY (with `key`s) so
     * each is an individual segment the group can rounded/separate — NOT wrapped in
     * a fragment (a fragment counts as one child and the per-button separator
     * injection would misfire). Omit for a plain single-select row (default —
     * matches every existing caller's output). The actions are SIBLINGS of the
     * select button (a `<Button>` can't nest another interactive element), so a
     * click on one never changes the selection.
     */
    itemAction?: (item: FlexWrapButtonRadioItem<T>) => ReactNode
}

/** Single-select mode (default) — exactly one value selected at a time. */
interface FlexWrapButtonRadioSingleProps<T extends string> extends FlexWrapButtonRadioBaseProps<T> {
    /** Single-select — omit or pass `false`. */
    multiple?: false
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a button is selected. */
    onChange: (value: T) => void
}

/**
 * Multi-select mode — a SET of values, each button an independent toggle. The
 * caller owns the set + the toggle logic (e.g. enforcing "at least one selected");
 * this component only reports which button was pressed via {@link onToggle}.
 */
interface FlexWrapButtonRadioMultiProps<T extends string> extends FlexWrapButtonRadioBaseProps<T> {
    /** Multi-select — pass `true`. */
    multiple: true
    /** Currently selected values. */
    values: Array<T>
    /** Fired with the pressed value (the caller adds/removes it from its own set). */
    onToggle: (value: T) => void
}

/** Props for the {@link FlexWrapButtonRadio} block — a discriminated union on `multiple`. */
export type FlexWrapButtonRadioProps<T extends string> =
    | FlexWrapButtonRadioSingleProps<T>
    | FlexWrapButtonRadioMultiProps<T>

/**
 * A single-select toggle-button group laid out as a flex-wrap row (buttons wrap
 * to the next line, never scroll). Every option is a real HeroUI `<Button>`:
 * standalone, selected = filled `tertiary` (NEUTRAL, not accent — a facet/config
 * toggle isn't a CTA), unselected = hollow `ghost` — clean, no own surface (the
 * parent card, or the bare page, is the surface). NEVER `primary` here — a config row commonly
 * sits on the SAME surface as the page's one accent CTA, and a solid-primary
 * selected pill would compete with it (1 accent-solid / surface, Von Restorff —
 * `accent-system`).
 *
 * When `itemAction` is supplied, each item instead renders as one connected
 * {@link ButtonGroup} — the select button + its action button(s) touching, only
 * the two outer ends rounded (`[select | delete | ...]`). No bordered frame: the button
 * VARIANTS carry the look — EVERY segment is filled `--default` so the cluster
 * reads as one solid control (the select pill is `secondary` = default fill +
 * accent text when chosen, else `tertiary` = default fill + neutral text — NOT a
 * hollow `ghost`, which would leave the unselected label floating on the page; the
 * action buttons are `tertiary` too). The seam is HeroUI's own
 * `ButtonGroup.Separator`, recoloured to the `--border` token (`!bg-border
 * !opacity-100`, overriding its default muddy `bg-current opacity-15`) so it
 * matches every other divider in the app. Because `.button` is
 * `position: relative`, the separator MUST live INSIDE the button that follows the
 * seam (its `left: -1px` then bites that button's left edge); so the component
 * injects one at the head of each action button's children — callers just return
 * plain `<Button>`s. Overridden to FULL height (`!top-0 !h-full`) from HeroUI's
 * default 50%.
 *
 * `role="group"` + `aria-pressed` per button — works for BOTH the default
 * single-select toggle group and the multi-select mode (`multiple`, a SET of
 * pressed toggles; the caller owns add/remove + any "keep ≥1 selected" rule). For
 * a grid with description/badge use `SelectableCardGroup`.
 *
 * @param props - {@link FlexWrapButtonRadioProps}
 * @see Story: .storybook/stories/blocks/navigation/FlexWrapButtonRadio/FlexWrapButtonRadio.stories
 */
export const FlexWrapButtonRadio = <T extends string>(props: FlexWrapButtonRadioProps<T>) => {
    const { items, ariaLabel, trailing, itemAction, className } = props
    // narrow the discriminated union once — selection state + the press handler are
    // the only things that differ between single- and multi-select.
    const isSelected = (candidate: T): boolean =>
        (props.multiple ? props.values.includes(candidate) : props.value === candidate)
    const onItemPress = (candidate: T): void => {
        if (props.multiple) {
            props.onToggle(candidate)
        } else {
            props.onChange(candidate)
        }
    }
    return (
        <div role="group" aria-label={ariaLabel} className={cn("flex flex-wrap items-center gap-2", className)}>
            {items.map((item) => {
                const selected = isSelected(item.value)
                if (!itemAction) {
                    // standalone: selected = filled `tertiary` (neutral, NOT accent —
                    // a facet toggle isn't a CTA), unselected = hollow `ghost` (no
                    // surface of its own — the page/card is the surface).
                    return (
                        <Button
                            key={item.value}
                            size="sm"
                            variant={selected ? "tertiary" : "ghost"}
                            isDisabled={item.isDisabled}
                            aria-pressed={selected}
                            onPress={() => onItemPress(item.value)}
                        >
                            {item.content}
                        </Button>
                    )
                }
                // select button + its action(s) = ONE connected ButtonGroup per
                // item. No border frame — the button variants carry the look; here
                // the unselected select is `tertiary` (filled `--default`), NOT
                // `ghost`, so it matches the filled action buttons instead of
                // floating hollow. Each action button gets a `ButtonGroup.Separator`
                // injected at the head of its children (HeroUI's separator must sit
                // INSIDE the following button — see the class doc), full-height.
                return (
                    <ButtonGroup key={item.value} size="sm" className="w-fit">
                        <Button
                            size="sm"
                            variant={selected ? "secondary" : "tertiary"}
                            isDisabled={item.isDisabled}
                            aria-pressed={selected}
                            onPress={() => onItemPress(item.value)}
                        >
                            {item.content}
                        </Button>
                        {React.Children.map(itemAction(item), (action) =>
                            React.isValidElement<{ children?: ReactNode }>(action)
                                ? React.cloneElement(
                                    action,
                                    undefined,
                                    <ButtonGroup.Separator className="!top-0 !h-full !bg-border !opacity-100" />,
                                    action.props.children,
                                )
                                : action,
                        )}
                    </ButtonGroup>
                )
            })}
            {trailing}
        </div>
    )
}

import React from "react"
import { Dropdown, Label } from "@heroui/react"
import { TranslateIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import type { NavbarLanguageOption } from "../types"

/** Props for {@link NavbarLanguageMenu}. */
export interface NavbarLanguageMenuProps {
    languages: Array<NavbarLanguageOption>
    activeLocale: string
    onLocaleChange: (code: string) => void
}

/**
 * Locale picker — raw HeroUI `Dropdown` (see file header: no atom here supports a
 * single-select CHECK indicator). Shared verbatim by the desktop icon row and the
 * mobile drawer row so the two never drift.
 */
export const NavbarLanguageMenu = ({ languages, activeLocale, onLocaleChange }: NavbarLanguageMenuProps) => (
    <Dropdown>
        <Button
            isIconOnly
            variant="ghost"
            prefixIcon={TranslateIcon}
            ariaLabel="Language"

        />
        <Dropdown.Popover>
            <Dropdown.Menu
                aria-label="Language"
                selectionMode="single"
                selectedKeys={new Set([activeLocale])}
