                                            () => (
                                                <StackH
                                                    principle="sibling-stack"
                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                    items={[
                                                        () => <Typography size="sm" text="Theme" />,
                                                        () => (
                                                            <NavbarThemeSwitch
                                                                isDarkMode={isDarkMode}
                                                                onThemeToggle={onThemeToggle}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                            ]}
                        />
                    )}
                />
            )}
        />
    )
}

export { Navbar }

"use client"

import React, {
    useEffect,
    useRef,
} from "react"
import type {
    ReactNode,
} from "react"
import {
    Accordion,
    Button,
    Input,
    Label,
    ScrollShadow,
    TextField,
    Typography,
    cn,
} from "@heroui/react"
import {
    ArrowRightIcon,
} from "@phosphor-icons/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { ContentMapRow } from "@/components/blocks/navigation/ContentMapRow"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"

/**
 * Placeholder group count the co-located skeleton mirrors while `isSkeleton`
 * is set — the real HeroUI `Accordion` and `ContentMapRow` below take no
 * `isSkeleton` of their own (missingSkeletonSupport), so this swaps in the
 * canonical `Skeleton.Accordion` piece right where the real tree sits.
 */
const SKELETON_GROUP_COUNT = 3

/** One selectable row inside an {@link OutlineRailGroup}. */
export interface OutlineRailItem {
    /** Stable id (accordion item key / scroll target). */
    id: string
    /** Row title (the row's accessible name). */
    title: string
    /** Highlights the row as the one currently open (accent tint). */
    isActive: boolean
    /** Read / completed — green check, highest-priority marker. */
    isRead: boolean
    /** Locked — the viewer cannot open it yet. */
    isLocked?: boolean
    /** Premium / VIP — star (shown when not locked). */
    isPremium?: boolean
    /** Optional right-aligned meta (e.g. minutes, score). */
    meta?: ReactNode
    /** Fired when the row is pressed (navigation handled by the caller). */
    onPress: () => void
}

/** One collapsible group (module / milestone) of {@link OutlineRailItem}s. */
export interface OutlineRailGroup {
    /** Stable id used as the accordion key + expand state. */
    id: string
    /** Group title (truncated + native tooltip). */
    title: string
    /** Group progress — expanded → a `ProgressMeter`; collapsed → {@link collapsedCountLabel}. */
    progress: { done: number; total: number }
    /** Pre-formatted "n/m" label shown when the group is collapsed. */
    collapsedCountLabel: string
    /** Rows in the group. */
    items: Array<OutlineRailItem>
}

/** The rail header — the rail's progress + one primary action. */
export interface OutlineRailHeader {
    /** Label for the overall-progress row (e.g. "Progress"). */
    label: ReactNode
    /** Overall progress driving the header meter. */
    progress: { done: number; total: number }
    /** Pre-formatted overall count (e.g. "2/12 lessons"). */
    countLabel: ReactNode
    /** Optional primary "continue / resume" action. */
    continue?: { label: ReactNode; onPress: () => void }
}

/** Controlled search box state for the rail. */
export interface OutlineRailSearch {
    /** Current query. */
    value: string
    /** Query change handler. */
    onChange: (value: string) => void
    /** Placeholder text. */
    placeholder: string
    /** Accessible label. */
    ariaLabel: string
}

/**
 * The list region's error / empty wiring. The loading state is no longer
 * carried here — it is the top-level {@link OutlineRailProps.isSkeleton},
 * which the list region mirrors co-located in place (no caller-supplied
 * `skeleton` tree).
 */
export interface OutlineRailAsync {
    /** Empty gate (no data at all). Ignored while {@link OutlineRailProps.isSkeleton} is set. */
    isEmpty: boolean
    /** Empty-state title. */
    emptyTitle: string
    /** Error-state title. */
    errorTitle: string
    /** Error to surface (prefer stale data once loaded; beats both skeleton and empty). */
    error?: unknown
    /** Retry handler. */
    onRetry: () => void
    /** Retry button label. */
    retryLabel: string
    /** Shown when a search filters everything out (groups present but empty). */
    noMatchLabel: string
}

/** Props for the {@link OutlineRail} block. */
export interface OutlineRailProps extends WithClassNames<undefined> {
    /** Progress header + continue action. Omit to hide the header (e.g. while loading). */
    header?: OutlineRailHeader
    /** Controlled search field. */
    search: OutlineRailSearch
    /** Ordered groups → rows. */
    groups: Array<OutlineRailGroup>
    /** Controlled expanded group ids. */
    expandedKeys: Set<string>
    /** Fires with the next expanded id set. */
    onExpandedChange: (keys: Set<string>) => void
    /**
     * First load, nothing in hand → the list region shimmers in place
     * (co-located: `Skeleton.Accordion` swaps in for the real `Accordion`
     * right where it sits — `missingSkeletonSupport`, `loading-and-skeleton.md`).
     * Owned by the caller's first-load formula, e.g. `!data && !error`.
     */
    isSkeleton?: boolean
    /** Error / empty wiring for the list region. */
    async: OutlineRailAsync
}

/**
 * The shared docs-style navigation rail (UI 2.0): a pinned progress header with a
 * single "continue" action, a client-side search field, then a scroll region of
 * collapsible groups → compact {@link ContentMapRow} rows. One progress bar at a
 * time — the open group shows a `ProgressMeter`, collapsed groups show a muted
 * "n/m" count.
 *
 * Props-only / fully controlled: the consuming feature owns the data, the search
 * value, the expanded-set (auto-open the active group, open matches on search),
 * and every string (i18n). Both the course content-map and the personal-project
 * milestone rail render through this one block, so they stay identical.
 *
 * Positioning (sticky / width / scroll height) is supplied by the caller via
 * `className`, so the same rail serves the desktop rail and the mobile drawer.
 *
 * @param props - {@link OutlineRailProps}
 * @see Story: .storybook/stories/blocks/navigation/OutlineRail/OutlineRail.stories
 */
export const OutlineRail = ({
    header,
    search,
    groups,
    expandedKeys,
    onExpandedChange,
    isSkeleton = false,
    async,
    className,
}: OutlineRailProps) => {
    /** Active row — scrolled into view when it changes / the list hydrates. */
    const activeRowRef = useRef<HTMLDivElement>(null)
    const activeItemId = groups
        .flatMap((group) => group.items)
        .find((item) => item.isActive)?.id
    useEffect(() => {
        activeRowRef.current?.scrollIntoView({ block: "nearest" })
    }, [activeItemId])

    return (
        <div className={cn("relative flex min-h-0 min-w-0 flex-col gap-3 p-6", className)}>
            {/* progress header — the "continue" action floats at the bottom (see below) */}
            {header ? (
                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between gap-2">
                        <Label>{header.label}</Label>
                        <Typography type="body-xs" color="muted">
                            {header.countLabel}
                        </Typography>
                    </div>
                    <ProgressMeter value={header.progress.done} max={header.progress.total} />
                </div>
            ) : null}

            {/* client-side search over the visible tree */}
            <TextField>
                <Input
                    aria-label={search.ariaLabel}
                    value={search.value}
                    onChange={(event) => search.onChange(event.target.value)}
                    placeholder={search.placeholder}
                />
            </TextField>

            {/* only the list scrolls — soft fade, header + search stay pinned. Extra bottom
                padding when the floating action is present so the last row clears it. */}
            <ScrollShadow hideScrollBar className={cn("-mx-1 min-h-0 min-w-0 flex-1 overflow-x-hidden overflow-y-auto px-1", header?.continue && "pb-20")}>
                {/* error beats a stale skeleton flag; empty only once settled (loading-and-skeleton.md §1) */}
                {async.error ? (
                    <AsyncContentError
                        title={async.errorTitle}
                        onRetry={async.onRetry}
                        retryLabel={async.retryLabel}
                    />
                ) : !isSkeleton && async.isEmpty ? (
                    <AsyncContentEmpty title={async.emptyTitle} />
                ) : isSkeleton ? (
                    // the real `Accordion` (HeroUI) and `ContentMapRow` below take no `isSkeleton`
                    // of their own — mirrored right here with the canonical `Skeleton.Accordion`
                    // piece instead of a caller-supplied parallel skeleton tree (missingSkeletonSupport).
                    <Skeleton.Accordion className="w-full" items={SKELETON_GROUP_COUNT} />
                ) : groups.length > 0 ? (
                    <Accordion
                        variant="default"
                        className="min-w-0 w-full"
                        expandedKeys={expandedKeys}
                        onExpandedChange={(keys) => onExpandedChange(new Set([...keys].map(String)))}
                    >
                        {groups.map((group) => {
                            const isExpanded = expandedKeys.has(group.id)
                            return (
                                <Accordion.Item
                                    key={group.id}
                                    id={group.id}
                                    aria-label={group.title}
                                    className="min-w-0"
                                >
                                    <Accordion.Heading className="min-w-0">
                                        <Accordion.Trigger className="min-w-0 w-full max-w-full px-0 py-2 hover:bg-transparent">
                                            {/* title truncates to one line; count/bar on the line below */}
                                            <div className="flex w-full min-w-0 items-center gap-2 overflow-hidden">
                                                <div className="flex min-w-0 flex-1 flex-col overflow-hidden">
                                                    <Typography
                                                        type="body"
                                                        weight="semibold"
                                                        truncate
                                                        title={group.title}
                                                        className="w-full min-w-0"
                                                    >
                                                        {group.title}
                                                    </Typography>
                                                    {isExpanded ? (
                                                        <ProgressMeter
                                                            value={group.progress.done}
                                                            max={group.progress.total || 1}
                                                        />
                                                    ) : (
                                                        <Typography type="body-xs" color="muted">
                                                            {group.collapsedCountLabel}
                                                        </Typography>
                                                    )}
                                                </div>
                                                <Accordion.Indicator className="shrink-0" />
                                            </div>
                                        </Accordion.Trigger>
                                    </Accordion.Heading>
                                    <Accordion.Panel>
                                        <Accordion.Body className="px-0 pb-3">
                                            <div className="flex flex-col gap-0">
                                                {group.items.map((item) => (
                                                    <div
                                                        key={item.id}
                                                        ref={item.isActive ? activeRowRef : undefined}
                                                    >
                                                        <ContentMapRow
                                                            title={item.title}
                                                            isActive={item.isActive}
                                                            isRead={item.isRead}
                                                            isLocked={item.isLocked}
                                                            isPremium={item.isPremium ?? false}
                                                            onPress={item.onPress}
                                                            meta={item.meta}
                                                        />
                                                    </div>
                                                ))}
                                            </div>
                                        </Accordion.Body>
                                    </Accordion.Panel>
                                </Accordion.Item>
                            )
                        })}
                    </Accordion>
                ) : (
                    <Typography type="body-sm" color="muted" align="center">
                        {async.noMatchLabel}
                    </Typography>
                )}
            </ScrollShadow>

            {/* the rail's one primary action — a frosted bottom bar so it stays reachable
                while the list scrolls behind it (was a static top button). The bar (px-6 py-3)
                is a click-through blur layer; only the full-width button catches the press. */}
            {header?.continue ? (
                <div className="pointer-events-none absolute inset-x-0 bottom-0 bg-background/80 px-6 py-3 backdrop-blur-md">
                    <Button
                        variant="primary"
                        size="lg"
                        onPress={header.continue.onPress}
                        className="pointer-events-auto w-full"
                    >
                        {header.continue.label}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                    </Button>
                </div>
            ) : null}
        </div>
    )
}

export default OutlineRail

import React, { useCallback, useMemo } from "react"
import { Pagination as HeroPagination, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link _Pagination} — presentational; every aria-label already resolved. */
export interface PaginationProps extends WithClassNames<undefined> {
    /** 1-based current page. */
    currentPage: number
    /** Total number of pages (>= 1). */
    totalPages: number
    /** Fired with a 1-based page number when the user changes page. */
    onPageChange: (pageNumber: number) => void
    /** Already-localized aria-label for the pagination nav landmark. */
    navAriaLabel: string
    /** Already-localized "Previous page" aria-label. */
    previousAriaLabel: string
    /** Already-localized "Next page" aria-label. */
    nextAriaLabel: string
}

/**
 * Generic, reusable page-based pagination control.
 *
 * Presentational + controlled: renders page links + prev/next from the supplied
 * page state and delegates navigation via `onPageChange`. The parent owns paging
 * (client-side or server-driven), so this stays reusable across any list.
 *
 * @param props - {@link PaginationProps}
 * @see Story: .storybook/stories/blocks/navigation/Pagination/Pagination.stories
 */
export const _Pagination = ({
    currentPage,
    totalPages,
    onPageChange,
    navAriaLabel,
    previousAriaLabel,
    nextAriaLabel,
    className,
}: PaginationProps) => {
    /** All 1-based page numbers to render (lists using this control are small). */
    const pageNumbers = useMemo(
        () => Array.from({ length: totalPages }, (_, index) => index + 1),
        [totalPages],
    )

    /** Go to the previous page, clamped to the first page. */
    const onPrevious = useCallback(
        () => onPageChange(Math.max(1, currentPage - 1)),
        [currentPage, onPageChange],
    )

    /** Go to the next page, clamped to the last page. */
    const onNext = useCallback(
        () => onPageChange(Math.min(totalPages, currentPage + 1)),
        [currentPage, totalPages, onPageChange],
    )

    return (
        <div className={cn("mt-6 flex justify-center", className)}>
            <HeroPagination aria-label={navAriaLabel} size="sm">
                <HeroPagination.Content className="flex flex-wrap justify-center gap-1">
                    <HeroPagination.Item>
                        <HeroPagination.Previous
                            aria-label={previousAriaLabel}
                            isDisabled={currentPage <= 1}
                            onPress={onPrevious}
                        >
                            <HeroPagination.PreviousIcon />
                        </HeroPagination.Previous>
                    </HeroPagination.Item>
                    {pageNumbers.map((pageNumber) => (
                        <PaginationLink
                            key={pageNumber}
                            pageNumber={pageNumber}
                            isActive={pageNumber === currentPage}
                            onPageChange={onPageChange}
                        />
                    ))}
                    <HeroPagination.Item>
                        <HeroPagination.Next
                            aria-label={nextAriaLabel}
                            isDisabled={currentPage >= totalPages}
                            onPress={onNext}
                        >
                            <HeroPagination.NextIcon />
                        </HeroPagination.Next>
                    </HeroPagination.Item>
                </HeroPagination.Content>
            </HeroPagination>
        </div>
    )
}

/** Props for {@link PaginationLink}. */
interface PaginationLinkProps {
    /** 1-based page number this link targets. */
    pageNumber: number
    /** Whether this link is the active page. */
    isActive: boolean
    /** Fired with this link's page number on press. */
    onPageChange: (pageNumber: number) => void
}

/**
