"use client"

import React from "react"
import type { ReactNode } from "react"
import { Breadcrumbs, cn } from "@heroui/react"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { HideAbove } from "@/components/frames/HideAbove"
import { resolveIdentity, type CallerIdentity } from "@/components/frames/_identity"

/** Collapse the full trail into a single "Back" once the path is this deep. */
const LONG_TRAIL_MIN = 4

/** One crumb in a {@link ResponsiveBreadcrumb} trail. */
export interface ResponsiveBreadcrumbItem {
    /** Stable key for the list. */
    key: string | number
    /** Crumb label. */
    label: ReactNode
    /** Navigate handler — omit on the current (last, read-only) crumb. */
    onPress?: () => void
}

/** Props for {@link ResponsiveBreadcrumb}. */
export interface ResponsiveBreadcrumbProps {
    /** The full trail, root → current (current last, usually without `onPress`). */
    items: Array<ResponsiveBreadcrumbItem>
    /**
     * Caller identity resolved on the always-mounted `Breadcrumbs` host (no wrapper).
     * The mobile/long-trail `BackLink` co-path does not accept CallerIdentity.
     */
    identity?: CallerIdentity
}

/**
 * Breadcrumb for a `PageHeader` `breadcrumb` slot. Shows the full
 * `Home › … › Current` trail on desktop when short; collapses to a single
 * {@link BackLink} ("Back") on mobile, or whenever the trail is long
 * (`>= {@link LONG_TRAIL_MIN}` crumbs) — a long trail wraps and eats vertical
 * space, and deep ancestors are already reachable from top nav. The back
 * target is the deepest clickable ancestor (last item with `onPress`). Pure
 * CSS for the mobile breakpoint; length check is render-time.
 *
 * @param props - {@link ResponsiveBreadcrumbProps}
 * @see Story: .storybook/stories/blocks/navigation/ResponsiveBreadcrumb/ResponsiveBreadcrumb.stories
 */
export const ResponsiveBreadcrumb = ({
    items,
    identity,
}: ResponsiveBreadcrumbProps) => {
    // back target = deepest ancestor we can navigate to (skips the current crumb)
    const parent = [...items].reverse().find((item) => item.onPress)
    const isLongTrail = items.length >= LONG_TRAIL_MIN
    const onBack = parent?.onPress

    return (
        <>
            {/* desktop + short trail: the full path — durable host for identity (always mounted) */}
            <Breadcrumbs
                {...resolveIdentity(identity, { tier: "block", name: "ResponsiveBreadcrumb" })}
                className={cn(isLongTrail ? "hidden" : "hidden @app-sm:flex")}
            >
                {items.map((item) => (
                    <Breadcrumbs.Item key={item.key} onPress={item.onPress}>
                        {item.label}
                    </Breadcrumbs.Item>
                ))}
            </Breadcrumbs>

            {/* mobile, or long trail on any width: single "Back" */}
            {onBack ? (
                isLongTrail ? (
                    <BackLink onPress={onBack} />
                ) : (
                    <HideAbove at="sm" body={() => <BackLink onPress={onBack} />} />
                )
            ) : null}
        </>
    )
}

export default ResponsiveBreadcrumb

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Card, Radio, RadioGroup, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One selectable card in a {@link SelectableCardGroup}. */
export interface SelectableCardItem<T extends string> {
    /** Value selected when this card is chosen. */
    value: T
    /** Primary label (text / icon + text). */
    label: ReactNode
    /** Optional secondary line under the label. */
    description?: ReactNode
    /** Optional leading icon (rendered decorative). */
    icon?: ReactNode
    /** When true the card is dimmed and not selectable. */
    isDisabled?: boolean
    /** Optional trailing node (e.g. a "coming soon" tag) shown on the right. */
    badge?: ReactNode
}

/** Props for the {@link SelectableCardGroup} block. */
export interface SelectableCardGroupProps<T extends string> extends WithClassNames<undefined> {
    /** The selectable cards (2+). */
    items: Array<SelectableCardItem<T>>
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a card is selected. */
    onChange: (value: T) => void
    /** Accessible label for the group. */
    ariaLabel: string
    /** Grid column count. Defaults to `2`. */
    columns?: 1 | 2 | 3
}

/** Tailwind grid-template class per supported column count. */
const COLUMNS_CLASS: Record<1 | 2 | 3, string> = {
    1: "grid-cols-1",
    2: "grid-cols-2",
    3: "grid-cols-3",
}

/**
 * A single-select group of surface cards: each option is a canonical HeroUI `Card`;
 * choosing one draws an accent OUTLINE ring around it (never a fill / colour change,
 * so the card stays neutral `bg-surface`). Built on HeroUI `RadioGroup`/`Radio`
 * (React Aria) so it is a real radio group — arrow-key roving, single-select
 * semantics, focus ring — not a hand-rolled toggle-button grid.
 *
 * The visible card is a `Card` styled off the `Radio` render-prop state
 * (`isSelected`/`isDisabled`/`isFocusVisible`). Selection/focus use `outline` (its own
 * CSS property) rather than a Tailwind `ring-*` — the `.card` base bakes an unlayered
 * `shadow-surface` box-shadow that would swallow a box-shadow ring, but never touches
 * `outline`. That same shadow is dropped (`!shadow-none`) while the ring is up so the
 * ring and the card elevation don't stack.
 *
 * Pick this for a larger "choose one of N cards" with icon / description / badge.
 * For a compact pill switch use `TabsCard` (`variant="primary"`); for section
 * navigation use `TabsCard` (`variant="secondary"`).
 *
 * @param props - {@link SelectableCardGroupProps}
 * @see Story: .storybook/stories/blocks/navigation/SelectableCardGroup/SelectableCardGroup.stories
 */
export const SelectableCardGroup = <T extends string>({
    items,
    value,
    onChange,
    ariaLabel,
    columns = 2,
    className,
}: SelectableCardGroupProps<T>) => (
        <RadioGroup
            aria-label={ariaLabel}
            value={value}
            onChange={(next) => onChange(next as T)}
            className={cn("grid gap-2", COLUMNS_CLASS[columns], className)}
        >
            {items.map((item) => (
                <Radio key={item.value} value={item.value} isDisabled={item.isDisabled} className="w-full">
                    <Radio.Content className="block w-full">
                        {({ isSelected, isDisabled, isFocusVisible }) => (
                            <Card
                                variant="default"
                                className={cn(
                                    "w-full text-sm text-foreground transition-colors",
                                    // selection & keyboard focus = an accent OUTLINE ring, NO
                                    // fill / colour change (see block doc for why outline, not
                                    // ring). Drop the card's `shadow-surface` while the ring is
                                    // up so the two elevations don't stack — `!` beats the
                                    // unlayered `.card` box-shadow.
                                    (isSelected || isFocusVisible) &&
                                        "outline outline-2 outline-accent outline-offset-0 !shadow-none",
                                    !isSelected && !isDisabled && "hover:bg-default",
                                    isDisabled && "opacity-60",
                                )}
                            >
                                <div className="flex w-full items-center gap-2">
                                    {item.icon ? (
                                        <span className="shrink-0" aria-hidden>
                                            {item.icon}
                                        </span>
                                    ) : null}
                                    <span className="flex min-w-0 flex-col">
                                        <span className="truncate">{item.label}</span>
                                        {item.description ? (
                                            <span className="truncate text-xs text-muted">{item.description}</span>
                                        ) : null}
                                    </span>
                                    {item.badge ? <span className="ml-auto shrink-0">{item.badge}</span> : null}
                                </div>
                            </Card>
                        )}
                    </Radio.Content>
                </Radio>
            ))}
        </RadioGroup>
    )

